SELECT
  json_extract(value, '$.operation') AS "operation",
  json_extract(value, '$.route') AS "route",
  json_extract(value, '$.coverage') AS "coverage",
  json_extract(value, '$.decision') AS "decision"
FROM json_each('[{"operation": "Chat through legacy inference", "route": "models/chat/completions?api-version=2024-05-01-preview in the demo", "coverage": "AzureAIModelApi; demo AzureAIModelAPI", "decision": "Current project route; track the SDK migration separately."}, {"operation": "Chat through OpenAI v1", "route": "openai/v1/chat/completions", "coverage": "No dedicated v1 adapter in the reviewed code", "decision": "An OpenAI-compatible client/adapter for deployments exposing this operation."}, {"operation": "Claude conversation", "route": "anthropic/v1/messages", "coverage": "AnthropicFoundryModelApi and demo companion", "decision": "Native Messages adapter; check the specific Claude version’s features."}, {"operation": "Document extraction / reranking", "route": "Model-specific parsing or reranking contract", "coverage": "Not implemented by these chat providers", "decision": "Cohere Parse is image-to-Markdown with no tool calling; use its documented operation. Reranking is a separate task."}, {"operation": "Embeddings", "route": "openai/v1/embeddings for compatible deployments", "coverage": "No embedding operation in IModelApi", "decision": "An embedding client and vector result type."}, {"operation": "Foundry project / agent operations", "route": "api/projects/<project> and its SDK-exposed APIs", "coverage": "Not supplied by these two providers", "decision": "Foundry project SDK for project features and platform-managed tools."}, {"operation": "Image generation / editing", "route": "Image API or vendor API; FLUX.2 uses providers/blackforestlabs/v1/flux-2-pro", "coverage": "Not implemented", "decision": "An image adapter with image inputs/outputs and the documented endpoint, version, and authentication."}, {"operation": "Managed compute / custom models", "route": "managed-deployments/<deployment>/; openai/v1 for compatible chat runtimes", "coverage": "No general managed-compute adapter", "decision": "Inspect the model runtime contract; compatible chat can share a protocol adapter."}, {"operation": "Realtime audio", "route": "WebSocket openai/v1/realtime, or WebRTC/SIP integration", "coverage": "Not implemented", "decision": "A session API with audio events and bidirectional transport."}, {"operation": "Responses", "route": "openai/v1/responses", "coverage": "No Responses adapter in the reviewed code", "decision": "Add item-based input/output and continuation support; verify model and region support."}]');
